import React, { useState, useEffect } from 'react';
import { OrderList } from 'primereact/orderlist';
import { ProductService } from './Service/ProductService';

export default function DragDrop() {
    const [products, setProducts] = useState([]);

    useEffect(() => {
        ProductService.getProductsSmall().then((data) => setProducts(data));
    }, []);

    const itemTemplate = (item) => {
        return (
            <div className="fxb wrap pd5 fvc gp3 w-100p">
                <img className="w90 h56 rds2 shrink-0" src={`https://primefaces.org/cdn/primereact/images/product/${item.image}`} alt={item.name} />
                <div className="fxb column">
                    <span className="font-size20 font-bold">{item.name}</span>
                    <div className="fxb fvc gp2">
                        <i className="pi pi-tag text-sm"></i>
                        <span>{item.category}</span>
                    </div>
                </div>
                <span className="font-bold font-size24 mgl-auto">${item.price}</span>
            </div>
        );
    };
    
    return (
        <OrderList dataKey="id" value={products} onChange={(e) => setProducts(e.value)} itemTemplate={itemTemplate} header="Products" dragdrop></OrderList>
    )

}